import { t, ui, locale, onLanguageChange } from './i18n.js';
import { agents } from './data.js';

const html=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const percent=value=>Number.isFinite(value)?`${Math.round(value*100)}%`:t('Non misurata');
const date=value=>{const d=new Date(value);return Number.isFinite(d.getTime())?new Intl.DateTimeFormat(locale(),{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(d):'—';};
const statuses={passed:'Attese rispettate',failed:'Da migliorare','needs-review':'Attese da rivedere'};
const field=(label,name,value='',area=false,max=160)=>ui`<div class="ops-field"><label for="evaluation-${name}">${html(label)}</label>${area?ui`<textarea id="evaluation-${name}" name="${name}" rows="4" maxlength="${max}" required>${html(value)}</textarea>`:ui`<input id="evaluation-${name}" name="${name}" value="${html(value)}" maxlength="${max}" required autocomplete="off">`}</div>`;
const empty=()=>({cases:[],runs:[],candidates:[],feedback:[],summary:{cases:0,stale:0,measured:0,passed:0,failed:0},limits:{expected:30,forbidden:30}});

export function createEvaluationsPanel({host,toast=()=>{},onVisibility=()=>{}}={}){
  let snapshot=empty(),context={scopeId:'business',scopes:[]},visible=false,loaded=false,loading=false,saving=false,busy=false,disposed=false,error='',generation=0,workspaceStamp='',view=null,localizeDialog=null;
  const controllers=new Set(),dialog=document.createElement('dialog');dialog.id='evaluations-dialog';dialog.className='ops-dialog evaluation-dialog';dialog.setAttribute('aria-labelledby','evaluation-dialog-title');document.body.append(dialog);
  const locked=()=>loading||saving||busy||disposed;
  const scopeName=id=>context.scopes.find(scope=>scope.id===id)?.name||id;
  const memory=id=>snapshot.candidates.find(item=>item.id===id),caseFor=id=>snapshot.cases.find(item=>item.id===id);
  const title=id=>memory(id)?.title||t("Memoria non più disponibile ({0})", {0: id});
  const eligible=(item,agentId)=>item.status==='confirmed'&&(item.scopeId===context.scopeId||item.scopeId==='shared'||item.sharedWith?.includes(context.scopeId))&&(!item.agentIds?.length||item.agentIds.includes(agentId));
  function accept(value){if(!value||!['cases','runs','candidates','feedback'].every(key=>Array.isArray(value[key])))throw Error(t('Le valutazioni non sono disponibili. Aggiorna lo stato.'));snapshot=value;loaded=true;}
  async function request(body,scopeId=context.scopeId){const controller=new AbortController();controllers.add(controller);try{const response=await fetch(body?'/api/evaluations':`/api/evaluations?scopeId=${encodeURIComponent(scopeId)}`,body?{method:'POST',headers:{'Content-Type':'application/json','X-Fuori-Studio':'local'},body:JSON.stringify(body),signal:controller.signal}:{cache:'no-store',signal:controller.signal});let value;try{value=await response.json();}catch{throw Error(t('La risposta delle valutazioni non è leggibile.'));}if(!response.ok)throw Object.assign(Error(value.error||t('Non è stato possibile completare la valutazione.')),{status:response.status});return value;}finally{controllers.delete(controller);}}
  function locks(){for(const parent of [host,dialog])parent.querySelectorAll('[data-evaluation-mutation],button[type="submit"]').forEach(button=>button.disabled=locked());host.querySelectorAll('[data-evaluation-action="reload"]').forEach(button=>button.disabled=loading||saving);host.setAttribute('aria-busy',String(loading||saving));}
  function render(){
    if(!visible)return;const summary=snapshot.summary||{},feedbackCandidates=snapshot.candidates.filter(item=>item.scopeId===context.scopeId&&item.status==='confirmed');
    host.innerHTML=ui`<div class="evaluation-heading"><div><span class="eyebrow">QUALITÀ DELLA MEMORIA</span><h3>Le informazioni giuste, quando servono.</h3><p>Definisci una domanda e le memorie che ti aspetti nel contesto di un agente. La prova usa il recupero reale dello studio, senza chiamate AI.</p></div><button type="button" class="knowledge-text-button" data-evaluation-action="close" aria-label="Chiudi valutazione memoria">Chiudi</button></div><div class="evaluation-tools"><button type="button" class="knowledge-button is-primary" data-evaluation-action="new" data-evaluation-mutation>＋ Nuovo caso</button><button type="button" class="knowledge-button" data-evaluation-action="reload"${loading||saving?' disabled':''}>Aggiorna</button><span>${html(scopeName(context.scopeId))}</span></div>${error?ui`<p class="evaluation-notice is-error" role="alert">${html(error)}</p>`:''}${loading&&!loaded?ui`<p class="evaluation-empty" role="status">Caricamento delle valutazioni…</p>`:ui`<div class="evaluation-summary"><div><strong>${summary.cases||0}</strong><span>Casi definiti da te</span></div><div><strong>${summary.measured||0}</strong><span>Prove sul contesto attuale</span></div><div><strong>${summary.passed||0}</strong><span>Attese rispettate</span></div><div><strong>${summary.stale||0}</strong><span>Attese da rivedere</span></div></div><div class="evaluation-cases">${snapshot.cases.map(item=>{const runs=snapshot.runs.filter(run=>run.caseId===item.id),latest=runs.at(-1);return ui`<article class="evaluation-case"><div class="evaluation-case-top"><h4>${html(item.title)}</h4><span class="evaluation-state${item.stale?.length||latest?.status==='failed'?' is-warning':''}">${item.stale?.length?t('Attese da rivedere'):latest?.current?html(t(statuses[latest.status])):latest?t('Prova da rieseguire'):t('Mai eseguito')}</span></div><p>${html(item.query)}</p><small>${html(agents.find(agent=>agent.id===item.agentId)?.name||item.agentId)} · ${item.expected.length} attese · ${item.forbidden.length} escluse</small><div class="evaluation-case-actions"><button type="button" class="knowledge-button is-primary" data-evaluation-action="run" data-id="${html(item.id)}" data-evaluation-mutation>Esegui prova</button><button type="button" class="knowledge-button" data-evaluation-action="edit" data-id="${html(item.id)}" data-evaluation-mutation>${item.stale?.length?t('Rivedi attese'):t('Modifica caso')}</button>${latest?ui`<button type="button" class="knowledge-button" data-evaluation-action="results" data-id="${html(item.id)}">Risultati</button>`:''}<button type="button" class="knowledge-text-button is-danger" data-evaluation-action="remove" data-id="${html(item.id)}" data-evaluation-mutation>Rimuovi</button></div></article>`;}).join('')||ui`<div class="evaluation-empty"><strong>La qualità parte da un caso concreto.</strong><p>Scegli una domanda legata al tuo lavoro e indica cosa dovrebbe essere recuperato. Senza attese definite non viene calcolato alcun punteggio.</p></div>`}</div><details class="evaluation-feedback-section"><summary>Utilità delle memorie in questo ambito</summary><p>Il tuo giudizio è distinto dai risultati delle prove. Puoi annotare un problema e correggere la memoria.</p><div class="evaluation-feedback-list">${feedbackCandidates.map(item=>{const feedback=snapshot.feedback.find(entry=>entry.memoryId===item.id);return ui`<article><div><strong>${html(item.title)}</strong><small>v${item.version} · ${feedback?.current?feedback.helpful?t('Utile secondo te'):t('Non utile secondo te'):feedback?t('Valutazione riferita a una versione precedente'):t('Non ancora valutata')}</small></div><div><button type="button" class="knowledge-button" data-evaluation-action="feedback" data-id="${html(item.id)}" data-evaluation-mutation>Valuta</button><button type="button" class="knowledge-text-button" data-evaluation-action="correct" data-id="${html(item.id)}" data-evaluation-mutation>Correggi</button></div></article>`;}).join('')||ui`<p class="evaluation-empty">Non ci sono memorie confermate salvate direttamente in questo ambito.</p>`}</div></details>`}<p class="evaluation-footnote">Queste prove misurano la selezione delle memorie rispetto alle tue attese. Non misurano la correttezza delle risposte AI né l’utilità del prodotto in generale.</p>`;locks();
  }
  async function load(){if(loading||saving||disposed)return;const version=++generation,scopeId=context.scopeId;loading=true;error='';render();try{const value=await request(undefined,scopeId);if(version===generation&&!disposed)accept(value);}catch(e){if(version===generation&&e.name!=='AbortError')error=e.message;}finally{if(version===generation){loading=false;render();}}}
  async function mutate(action,payload){const scopeId=context.scopeId,result=await request({action,payload});if(scopeId===context.scopeId)accept(result);render();return result;}
  function shell(title,body,footer){dialog.innerHTML=ui`<div class="ops-dialog-heading"><div><div class="eyebrow">QUALITÀ DELLA MEMORIA</div><h2 id="evaluation-dialog-title">${html(title)}</h2></div><button type="button" class="ops-icon" data-evaluation-close aria-label="Chiudi finestra">✕</button></div>${body}<div class="ops-dialog-footer">${footer||ui`<button type="button" class="ops-button" data-evaluation-close>Chiudi</button>`}</div>`;if(!dialog.open)dialog.showModal();locks();}
  function form(title,body,label,submit,{after}={}){view={kind:'form'};shell(title,ui`<form id="evaluation-form"><div class="ops-form-body">${body}</div><p class="ops-form-error" role="alert" hidden></p></form>`,ui`<button type="button" class="ops-button" data-evaluation-close>Annulla</button><button type="submit" form="evaluation-form" class="ops-button is-primary" data-evaluation-mutation>${html(label)}</button>`);dialog.querySelector('form').addEventListener('submit',async event=>{event.preventDefault();if(locked())return;const el=event.currentTarget;if(!el.reportValidity())return;const data=new FormData(el),box=dialog.querySelector('.ops-form-error');saving=true;box.hidden=true;locks();try{const result=await submit(data);if(!disposed){dialog.close();saving=false;after?.(result);}}catch(e){if(!disposed){box.textContent=e.status===409?t("{0} Aggiorna prima di riprovare.", {0: e.message}):e.message;box.hidden=false;}}finally{saving=false;locks();}});}
  function choices(name,items,selected=[]){return items.map(item=>ui`<label class="evaluation-choice" data-memory-title="${html(item.title.toLocaleLowerCase(locale()))}"><input type="checkbox" name="${name}" value="${html(item.id)}"${selected.includes(item.id)?' checked':''}><span><strong>${html(item.title)}</strong><small>${html(scopeName(item.scopeId))} · v${item.version}${item.status==='confirmed'?'':t(' · proposta')}</small></span></label>`).join('')||ui`<p class="ops-hint">Nessuna memoria disponibile per questa selezione.</p>`;}
  function edit(item,draft){localizeDialog=()=>{const form=dialog.querySelector('form'),data=new FormData(form);edit(item,{agentId:data.get('agentId'),expectedIds:data.getAll('expectedIds'),forbiddenIds:data.getAll('forbiddenIds'),filter:dialog.querySelector('#evaluation-filter').value});};const scopeId=context.scopeId,agentId=draft?.agentId||item?.agentId||'nova';form(item?t('Rivedi le attese del caso'):t('Un caso da verificare'),ui`<p class="ops-form-intro">Ambito: <strong>${html(scopeName(scopeId))}</strong>. Sei tu a definire le memorie attese e quelle che devono restare escluse.</p>${item?.stale?.length?ui`<p class="evaluation-notice">Alcune memorie o i loro permessi sono cambiati. Rivedi i gruppi: il salvataggio conferma le versioni attuali. Le memorie eliminate non sono più selezionabili.</p>`:''}${field(t('Nome del caso'),'title',item?.title)}${field(t('Domanda o richiesta da simulare'),'query',item?.query,true,4000)}<div class="ops-field"><label for="evaluation-agent">Agente che riceve il contesto</label><select id="evaluation-agent" name="agentId">${agents.map(agent=>ui`<option value="${html(agent.id)}"${agent.id===agentId?' selected':''}>${html(agent.name)}</option>`).join('')}</select></div><div class="ops-field"><label for="evaluation-filter">Filtra le memorie nei due gruppi</label><input id="evaluation-filter" type="search" maxlength="200" autocomplete="off" placeholder="Cerca un titolo…"></div><fieldset class="evaluation-choices"><legend>Memorie attese · massimo 30</legend><p class="ops-hint">Solo confermate e autorizzate per questo agente e ambito.</p><div id="evaluation-expected">${choices('expectedIds',snapshot.candidates.filter(memory=>eligible(memory,agentId)),draft?.expectedIds||item?.expected.map(ref=>ref.id))}</div></fieldset><fieldset class="evaluation-choices"><legend>Memorie che devono restare escluse · massimo 30</legend><p class="ops-hint">Puoi scegliere note di altri ambiti per verificare la separazione del contesto. Questa selezione non le condivide con l’agente.</p><div id="evaluation-forbidden">${choices('forbiddenIds',snapshot.candidates,draft?.forbiddenIds||item?.forbidden.map(ref=>ref.id))}</div></fieldset>`,t('Conferma attese e salva'),async data=>{const expectedIds=data.getAll('expectedIds'),forbiddenIds=data.getAll('forbiddenIds');if(!expectedIds.length&&!forbiddenIds.length)throw Error(t('Scegli almeno una memoria attesa o esclusa.'));if(expectedIds.length>30||forbiddenIds.length>30)throw Error(t('Scegli al massimo 30 memorie per gruppo.'));if(expectedIds.some(id=>forbiddenIds.includes(id)))throw Error(t('La stessa memoria non può essere attesa e da escludere.'));return mutate('saveCase',{...(item?{id:item.id,expectedVersion:item.version}:{}),scopeId,title:data.get('title').trim(),query:data.get('query').trim(),agentId:data.get('agentId'),expectedIds,forbiddenIds});},{after:()=>toast(t('Caso salvato. Esegui la prova per verificare le tue attese.'))});
    const filter=()=>{const query=dialog.querySelector('#evaluation-filter').value.toLocaleLowerCase(locale());dialog.querySelectorAll('[data-memory-title]').forEach(row=>row.hidden=!row.dataset.memoryTitle.includes(query));};dialog.querySelector('#evaluation-filter').addEventListener('input',filter);dialog.querySelector('[name="agentId"]').addEventListener('change',event=>{const ids=[...dialog.querySelectorAll('[name="expectedIds"]:checked')].map(input=>input.value);dialog.querySelector('#evaluation-expected').innerHTML=choices('expectedIds',snapshot.candidates.filter(memory=>eligible(memory,event.target.value)),ids);filter();});if(draft){dialog.querySelector('#evaluation-filter').value=draft.filter;filter();}
  }
  function memoryList(ids){return ids.length?ui`<ul class="evaluation-memory-list">${ids.map(id=>ui`<li><span>${html(title(id))}</span>${memory(id)?ui`<button type="button" class="ops-text-button" data-evaluation-action="correct" data-id="${html(id)}" data-evaluation-mutation>Apri memoria</button>`:''}</li>`).join('')}</ul>`:ui`<p class="evaluation-none">Nessuna.</p>`;}
  function results(id,runId){const item=caseFor(id);if(!item)return;const runs=snapshot.runs.filter(run=>run.caseId===id),run=runs.find(run=>run.id===runId)||runs.at(-1);if(!run)return;view={kind:'results',id,runId:run.id};shell(item.title,ui`<div class="ops-task-body evaluation-result"><div class="evaluation-result-top"><span class="evaluation-state${run.status!=='passed'?' is-warning':''}">${html(t(statuses[run.status]))}</span><span>${html(date(run.at))} · ${Math.max(0,Number(run.elapsedMs)||0)} ms</span></div><div class="ops-field"><label for="evaluation-result-history">Prova conservata</label><select id="evaluation-result-history">${runs.slice().reverse().map(entry=>ui`<option value="${html(entry.id)}"${entry.id===run.id?' selected':''}>${html(date(entry.at))} · ${html(t(statuses[entry.status]))}${entry.current?t(' · attuale'):t(' · storica')}</option>`).join('')}</select></div>${!run.current?ui`<p class="evaluation-notice">Il contesto o il caso sono cambiati dopo questa prova. Il risultato descrive lo stato precedente: rivedi le attese se necessario e riesegui.</p>`:''}${run.selected.some(selected=>selected.truncated)?ui`<p class="evaluation-notice">Alcune memorie sono state abbreviate per il limite di contesto. La copertura conta la loro presenza, non garantisce che ogni dettaglio del testo sia incluso.</p>`:''}${run.stale?.length?ui`<section><h3>Attese da rivedere</h3>${memoryList(run.stale)}</section>`:''}<div class="evaluation-measures"><div><span>Copertura delle memorie attese</span><strong>${percent(run.recall)}</strong><small>Attese recuperate / attese definite da te.</small></div><div><span>Quota attesa del contesto</span><strong>${percent(run.expectedShare)}</strong><small>Attese recuperate / memorie selezionate. Altre memorie possono essere utili.</small></div></div><section><h3>Memorie attese mancanti</h3>${memoryList(run.missing||[])}</section><section><h3>Memorie da escludere che sono state recuperate</h3>${memoryList(run.forbidden||[])}</section>${run.violations?.length?ui`<section><h3>Violazioni dei permessi osservate</h3>${memoryList(run.violations)}</section>`:''}<section><h3>Contesto effettivamente selezionato</h3><ol class="evaluation-selected">${run.selected.map(selected=>ui`<li><span class="evaluation-rank">${selected.rank}</span><div><strong>${html(title(selected.id))}</strong><small>Versione ${selected.version}${selected.truncated?t(' · testo abbreviato per il limite di contesto'):''}</small></div>${memory(selected.id)?ui`<button type="button" class="ops-text-button" data-evaluation-action="correct" data-id="${html(selected.id)}" data-evaluation-mutation>Apri</button>`:''}</li>`).join('')||ui`<li class="evaluation-none">Nessuna memoria selezionata in questa prova.</li>`}</ol></section><p class="evaluation-footnote">La selezione riproduce il recupero della memoria; nessun prompt viene inviato a un modello AI. Una prova superata vale per questo caso e queste versioni.</p></div>`,ui`<button type="button" class="ops-button" data-evaluation-close>Chiudi</button><button type="button" class="ops-button" data-evaluation-action="edit" data-id="${html(id)}" data-evaluation-mutation>Rivedi attese</button><button type="button" class="ops-button is-primary" data-evaluation-action="run" data-id="${html(id)}" data-evaluation-mutation>Esegui di nuovo</button>`);dialog.querySelector('#evaluation-result-history').addEventListener('change',event=>results(id,event.target.value));}
  async function run(item){saving=true;locks();try{await mutate('runCase',{id:item.id,expectedVersion:item.version});saving=false;results(item.id);}catch(e){toast(e.message);}finally{saving=false;locks();}}
  function remove(item){localizeDialog=()=>remove(item);form(t('Rimuovi il caso e le sue prove'),ui`<p><strong>${html(item.title)}</strong></p><p>Rimuove questo caso e tutta la sua cronologia di valutazione. Le memorie rimangono nello studio.</p>`,t('Rimuovi caso e prove'),()=>mutate('removeCase',{id:item.id,expectedVersion:item.version}),{after:()=>toast(t('Caso e prove rimossi.'))});}
  function feedback(item){localizeDialog=()=>feedback(item);const previous=snapshot.feedback.find(entry=>entry.memoryId===item.id);form(t('Quanto ti è utile questa memoria?'),ui`<p class="ops-form-intro"><strong>${html(item.title)}</strong> · versione ${item.version}</p><fieldset class="evaluation-choices"><legend>Il tuo giudizio sulla versione attuale</legend><label class="ops-check"><input type="radio" name="helpful" value="yes" required${previous?.current&&previous.helpful?' checked':''}><span>Utile</span></label><label class="ops-check"><input type="radio" name="helpful" value="no" required${previous?.current&&!previous.helpful?' checked':''}><span>Non utile</span></label></fieldset><div class="ops-field"><label for="evaluation-note">Cosa funziona o cosa va corretto · facoltativo</label><textarea id="evaluation-note" name="note" rows="4" maxlength="1000">${html(previous?.note||'')}</textarea></div><p class="ops-hint">Il giudizio non modifica il contenuto della memoria. Usa Correggi per rivedere l’informazione.</p>`,t('Salva valutazione'),async data=>{await request({action:'feedback',payload:{memoryId:item.id,memoryVersion:item.version,...(previous?{expectedVersion:previous.version}:{}),helpful:data.get('helpful')==='yes',note:data.get('note').trim()}});accept(await request());render();},{after:()=>toast(t('Valutazione salvata sulla versione attuale.'))});}
  function click(event){if(event.target.closest('[data-evaluation-close]')){if(!saving)dialog.close();return;}const button=event.target.closest('[data-evaluation-action]');if(!button||button.disabled)return;const {evaluationAction:action,id}=button.dataset;if(action==='close'){setVisible(false);return;}if(action==='reload'){void load();return;}if(action==='results'){results(id);return;}if(locked())return;if(action==='new')edit();if(action==='edit'&&caseFor(id))edit(caseFor(id));if(action==='run'&&caseFor(id))void run(caseFor(id));if(action==='remove'&&caseFor(id))remove(caseFor(id));if(action==='feedback'&&memory(id))feedback(memory(id));if(action==='correct'&&memory(id)){dialog.close();window.dispatchEvent(new CustomEvent('studio-edit-memory',{detail:{id}}));}}
  function setVisible(value){visible=Boolean(value);host.hidden=!visible;onVisibility(visible);render();if(visible&&!loading)void load();}
  host.addEventListener('click',click);dialog.addEventListener('click',click);dialog.addEventListener('cancel',event=>{if(saving)event.preventDefault();});dialog.addEventListener('close',()=>{if(!dialog.open)view=null;});
  const unsubscribeLanguage=onLanguageChange(()=>{if(disposed)return;render();if(dialog.open&&!saving){if(view?.kind==='results')results(view.id,view.runId);else localizeDialog?.();}});
  function expire(){disposed=true;generation++;controllers.forEach(controller=>controller.abort());dialog.close();dialog.replaceChildren();host.replaceChildren();snapshot=empty();}window.addEventListener('studio-session-expired',expire);
  return {setVisible,toggle(){setVisible(!visible);},refresh:load,setBusy(value){busy=Boolean(value);locks();},setContext(value){const stamp=JSON.stringify((value.memories||[]).map(item=>[item.id,item.version,item.status,item.sharedWith,item.agentIds])),changed=value.scopeId!==context.scopeId||stamp!==workspaceStamp;context={...context,...value};workspaceStamp=stamp;if(changed){generation++;loading=false;loaded=false;snapshot=empty();error='';if(dialog.open&&!saving)dialog.close();if(visible&&!saving)void load();}render();},dispose(){unsubscribeLanguage();expire();window.removeEventListener('studio-session-expired',expire);host.removeEventListener('click',click);dialog.remove();}};
}
